    has_suffix = low.endswith('.flf') or low.endswith('.tlf')
    if has_suffix:
        rels = [fontname]
    else:
        rels = [fontname + '.flf', fontname + '.tlf', fontname]
    if '/' in fontname:
        names.extend(rels)
    else:
        for r in rels:
            names.append(os.path.join(fontdir, r))
        for r in rels:
            names.append(r)
    # Preserve order, drop duplicates
    out=[]
    for n in names:
        if n not in out:
            out.append(n)
    return out


