        if os.path.isfile(p):
            return p
    return None


def find_control(fontdir, name):
    rels = [name] if name.lower().endswith('.flc') else [name + '.flc', name]
    names=[]
    if '/' in name:
        names = rels
    else:
        for r in rels: names.append(os.path.join(fontdir, r))
        for r in rels: names.append(r)
    seen=[]
    for n in names:
        if n in seen: continue
        seen.append(n)
        if os.path.isfile(n): return n
