def smush_pair(l, r, rules, hardblank, universal=False):
    if l == ' ': return r
    if r == ' ': return l
    if universal:
        if l == hardblank and r == hardblank:
            return hardblank
        return r
    if (rules & 1) and l == r and l != hardblank:
        return l
    if (rules & 2):
        chars = '|/\\[]{}()<>'
        if l == '_' and r in chars: return r
        if r == '_' and l in chars: return l
    if (rules & 4):
        groups = ['|', '/\\', '[]', '{}', '()', '<>']
        gl = gr = -1
        for i,g in enumerate(groups):
            if l in g: gl = i
            if r in g: gr = i
        if gl >= 0 and gr >= 0 and gl != gr:
            return r if gr > gl else l
    if (rules & 8):
        if (l, r) in [('[',']'), (']','['), ('{','}'), ('}','{'), ('(',')'), (')','(')]:
            return '|'
    if (rules & 16):
        if l == '/' and r == '\\': return '|'
        if l == '\\' and r == '/': return 'Y'
        if l == '>' and r == '<': return 'X'
    if (rules & 32) and l == hardblank and r == hardblank:
        return hardblank
    return None


def overlay(lines, glyph, overlap, rules, hardblank, universal=False):
    out=[]
    h=len(lines)
    for i in range(h):
        left = lines[i]
        right = glyph[i]
        if overlap <= 0:
            out.append(left + right)
            continue
        # pad left if overlap reaches before beginning
        if overlap > len(left):
            left = ' ' * (overlap - len(left)) + left
        prefix = left[:-overlap] if overlap else left
        mid=[]
        for k in range(overlap):
            lc = left[len(left)-overlap+k] if len(left)-overlap+k >= 0 else ' '
            rc = right[k] if k < len(right) else ' '
            sc = smush_pair(lc, rc, rules, hardblank, universal)
            if sc is None:
                sc = rc if rc != ' ' else lc
            mid.append(sc)
        suffix = right[overlap:] if overlap < len(right) else ''
        out.append(prefix + ''.join(mid) + suffix)
