        g = [(glyph[i] if i < len(glyph) else '') for i in range(font.height)]
        if all(len(x)==0 for x in lines):
            lines = g[:]
        else:
            o, uni = choose_overlap(lines, g, layout_mode, rules, font.hardblank)
            lines = overlay(lines, g, o, rules, font.hardblank, universal=uni)
