def visible_lines(lines, hardblank):
    return [l.replace(hardblank, ' ') for l in lines]


def max_line_len(lines):
    return max((len(x) for x in lines), default=0)


def justify(lines, width, just):
    if just == 'left':
        return lines
    maxw = max(1, width - 1)
    out=[]
    for l in lines:
        if just == 'right':
            pad = max(0, maxw - len(l))
        else:
            pad = max(0, (maxw - len(l)) // 2)
        out.append(' ' * pad + l)
    return out


def render_stream_text(text, font, layout_mode, rules, width, just, direction=0, paragraph=False):
