def apply_controls(text, controls, german=False):
    maps=[]
    if german:
        maps.append({'@':'§','[':'Ä','\\':'Ö',']':'Ü','{':'ä','|':'ö','}':'ü','~':'ß'})
    maps.extend(controls)
    if not maps:
        return text
    out=[]
    for ch in text:
        c=ch
        for m in maps:
            c=m.get(c,c)
        out.append(c)
    return ''.join(out)


def build_message(args):
    if not args:
        return None
    out=[]
    prev_nonempty=False
    for a in args:
        if a == '':
            if prev_nonempty:
                out.append(' ')
            out.append('\n')
            prev_nonempty=False
        else:
            if prev_nonempty:
                out.append(' ')
            out.append(a)
            prev_nonempty=True
