class Opts:
    def __init__(self):
        self.fontdir=DEFAULT_FONTDIR
        self.font=DEFAULT_FONT
        self.width=80
        self.just='auto'
        self.direction='font'
        self.paragraph=False
        self.layout_request=None  # None, full,kern,smush,force_smush,overlap, explicit
        self.explicit_rules=None
        self.info=-1
        self.operands=[]
        self.german=False
        self.controls=[]
        self.control_files=[]


def usage(prog):
    return USAGE_TPL.format(prog=prog)


def parse_args(argv):
    opts=Opts()
    prog_path=argv[0] if argv else 'executable'
    prog=os.path.basename(prog_path)
    req=set('dfmwCI')
    simple=set('cklnoprstvxDELNRSWX')
    i=1
    endopts=False
    while i < len(argv):
        arg=argv[i]
        if endopts or arg == '-' or not (arg.startswith('-') and len(arg)>1):
            opts.operands.append(arg); i+=1; continue
        if arg == '--':
            opts.operands.extend(argv[i+1:]); break
        j=1
        while j < len(arg):
            ch=arg[j]
            if ch in req:
                if j+1 < len(arg):
                    val=arg[j+1:]; j=len(arg)
                else:
                    if i+1 >= len(argv):
                        sys.stderr.write(f"{prog_path}: option requires an argument -- '{ch}'\n")
                        sys.stderr.write(usage(prog)); return None, 1
                    i+=1; val=argv[i]; j=len(arg)
                if ch == 'd': opts.fontdir=val
                elif ch == 'f': opts.font=val
                elif ch == 'w':
                    try: opts.width=int(val)
                    except Exception: pass
                    if opts.width < 1: opts.width=80
                elif ch == 'm':
                    try: mv=int(val)
                    except Exception: mv=0
                    if mv == 0: opts.layout_request='kern'
                    elif mv == -1: opts.layout_request='full'
                    elif mv == -2: opts.layout_request='smush'
                    elif 1 <= mv <= 63:
                        opts.layout_request='explicit'; opts.explicit_rules=mv
                elif ch == 'C':
                    opts.control_files.append(val)
                elif ch == 'I':
                    try: opts.info=int(val)
                    except Exception: opts.info=0
                break
            elif ch in simple:
                if ch == 'c': opts.just='center'
                elif ch == 'l': opts.just='left'
                elif ch == 'r': opts.just='right'
                elif ch == 'x': opts.just='auto'
                elif ch == 'p': opts.paragraph=True
                elif ch == 'n': opts.paragraph=False
                elif ch == 'D': opts.german=True
                elif ch == 'E': opts.german=False
                elif ch == 'N': opts.control_files=[]; opts.controls=[]
                elif ch == 'L': opts.direction='ltr'
                elif ch == 'R': opts.direction='rtl'
                elif ch == 'X': opts.direction='font'
                elif ch == 'v': opts.info=0
                elif ch == 't':
                    try:
                        sz=shutil.get_terminal_size(fallback=(opts.width, 24))
                        if sz.columns > 0 and sys.stdout.isatty(): opts.width=sz.columns
                    except Exception: pass
                elif ch == 's': opts.layout_request='smush'
                elif ch == 'S': opts.layout_request='force_smush'
                elif ch == 'k': opts.layout_request='kern'
                elif ch == 'W': opts.layout_request='full'
                elif ch == 'o': opts.layout_request='overlap'
