    elif opts.layout_request == 'kern': mode='kern'; rules=0
    elif opts.layout_request == 'overlap': mode='overlap'; rules=0
    elif opts.layout_request == 'explicit': mode='smush'; rules=opts.explicit_rules or 0
    elif opts.layout_request == 'force_smush':
        mode='smush'; rules = (font.fulllayout & 63) if font.fulllayout is not None else (font.oldlayout & 63 if font.oldlayout>0 else 0)
        if rules == 0: mode='overlap'
    elif opts.layout_request == 'smush':
        # Respect fonts whose declared default is fitting or full width.
        dm, dr = font_default_mode(font)
        if dm == 'smush': mode='smush'; rules=dr
        else: mode=dm; rules=dr
    direction = font.printdir
    if opts.direction == 'ltr': direction=0
    elif opts.direction == 'rtl': direction=1
    just=opts.just
    if just == 'auto':
        just = 'right' if direction == 1 else 'left'
    msg=build_message(opts.operands)
    if msg is None:
        data=sys.stdin.buffer.read()
        # Classic FIGlet treats input as bytes unless UTF-8 control mode is used;
        # latin-1 preserves byte values for bundled FIGfonts.
        try: msg=data.decode('latin-1')
        except Exception: msg=data.decode('utf-8','ignore')
    msg=apply_controls(msg, control_maps, opts.german)
    lines=render_stream_text(msg, font, mode, rules, opts.width, just, direction, opts.paragraph)
    # Output as UTF-8 if needed, but latin-1 bytes for raw legacy characters.
    out=''.join(l + '\n' for l in lines)
    try:
        sys.stdout.buffer.write(out.encode('utf-8' if font.is_tlf else 'latin-1'))
    except UnicodeEncodeError:
        sys.stdout.buffer.write(out.encode('utf-8'))
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv))
