class Font:
    def __init__(self):
        self.hardblank = '$'
        self.height = 1
        self.baseline = 1
        self.maxlen = 1
        self.oldlayout = 0
        self.commentlines = 0
        self.printdir = 0
        self.fulllayout = None
        self.codetag_count = 0
        self.glyphs = {}
        self.is_tlf = False


def strip_suffix_font_name(name):
    low = name.lower()
    if low.endswith('.flf') or low.endswith('.tlf'):
        return name[:-4]
    return name


def decode_font_bytes(data):
    # TOIlet fonts and many modern FIGfonts are UTF-8; older FIGfonts may contain
    # raw 8-bit characters.  UTF-8 with a latin-1 fallback preserves the bundled data.
    if data.startswith(b'tlf2'):
        return data.decode('utf-8', 'replace')
    try:
        return data.decode('utf-8')
    except UnicodeDecodeError:
        return data.decode('latin-1')


def looks_like_tag(line):
    s = line.strip()
    if not s:
        return False
    tok = s.split()[0]
    return bool(re.fullmatch(r'(?:0[xX][0-9A-Fa-f]+|[0-9]+)', tok))


def parse_code_tag(line):
    tok = line.strip().split()[0]
    try:
        if tok.lower().startswith('0x'):
            return int(tok, 16)
        return int(tok, 10)
    except Exception:
        return None


def strip_glyph_line(line, is_last=False):
    if line.endswith('\r'):
        line = line[:-1]
    if not line:
        return ''
    marker = line[-1]
    line = line[:-1]
    if marker != ' ':
        while line.endswith(marker):
            line = line[:-1]
    return line


def read_glyph(lines, idx, height):
    g = []
    for r in range(height):
        if idx >= len(lines):
            raw = ''
        else:
            raw = lines[idx]
        g.append(strip_glyph_line(raw, r == height-1))
        idx += 1
    return g, idx


def load_font(path):
    data = open(path, 'rb').read()
    text = decode_font_bytes(data)
    lines = text.splitlines()
    if not lines:
        raise ValueError('empty')
    header = lines[0]
    if not (header.startswith('flf2a') or header.startswith('tlf2a')):
        raise ValueError('bad')
    f = Font()
    f.is_tlf = header.startswith('tlf2a')
    f.hardblank = header[5] if len(header) > 5 else '$'
    rest = header[6:].strip().split()
    nums = []
    for x in rest:
        try:
            nums.append(int(x))
        except Exception:
            nums.append(0)
    while len(nums) < 5:
        nums.append(0)
    f.height, f.baseline, f.maxlen, f.oldlayout, f.commentlines = nums[:5]
    if len(nums) >= 6: f.printdir = nums[5]
    if len(nums) >= 7: f.fulllayout = nums[6]
    if len(nums) >= 8: f.codetag_count = nums[7]
    idx = 1 + f.commentlines
    # Required ASCII 32..126
    for cp in range(32, 127):
        g, idx = read_glyph(lines, idx, f.height)
        f.glyphs[cp] = g
    # Optional Deutsch characters in traditional order, if present before tags.
    if idx < len(lines) and not looks_like_tag(lines[idx]):
        save = idx
        ok = True
        glyphs = []
        for _ in range(7):
            if idx + f.height > len(lines):
                ok = False; break
            g, idx = read_glyph(lines, idx, f.height)
            glyphs.append(g)
        if ok:
            for cp, g in zip(GERMAN_CODES, glyphs):
                f.glyphs[cp] = g
        else:
            idx = save
    # Code-tagged glyphs: tag line followed by height glyph lines.
    while idx < len(lines):
        if not looks_like_tag(lines[idx]):
            idx += 1
            continue
        cp = parse_code_tag(lines[idx])
        idx += 1
        if cp is None or idx + f.height > len(lines) + 1:
            continue
        g, idx = read_glyph(lines, idx, f.height)
        f.glyphs[cp] = g
    return f


def candidates_for_font(fontdir, fontname):
    names = []
    low = fontname.lower()
    has_suffix = low.endswith('.flf') or low.endswith('.tlf')
    if has_suffix:
        rels = [fontname]
    else:
        rels = [fontname + '.flf', fontname + '.tlf', fontname]
    if '/' in fontname:
        names.extend(rels)
    else:
        for r in rels:
            names.append(os.path.join(fontdir, r))
        for r in rels:
            names.append(r)
    # Preserve order, drop duplicates
    out=[]
    for n in names:
        if n not in out:
            out.append(n)
    return out


def find_font(fontdir, fontname):
    for p in candidates_for_font(fontdir, fontname):
        if os.path.isfile(p):
            return p
    return None


def find_control(fontdir, name):
    rels = [name] if name.lower().endswith('.flc') else [name + '.flc', name]
    names=[]
    if '/' in name:
        names = rels
    else:
        for r in rels: names.append(os.path.join(fontdir, r))
        for r in rels: names.append(r)
    seen=[]
    for n in names:
        if n in seen: continue
        seen.append(n)
        if os.path.isfile(n): return n
    return None


def smush_pair(l, r, rules, hardblank, universal=False):
    if l == ' ': return r
    if r == ' ': return l
    if universal:
        if l == hardblank and r == hardblank:
            return hardblank
        return r
    if (rules & 1) and l == r and l != hardblank:
        return l
    if (rules & 2):
        chars = '|/\\[]{}()<>'
        if l == '_' and r in chars: return r
        if r == '_' and l in chars: return l
    if (rules & 4):
        groups = ['|', '/\\', '[]', '{}', '()', '<>']
        gl = gr = -1
        for i,g in enumerate(groups):
            if l in g: gl = i
            if r in g: gr = i
        if gl >= 0 and gr >= 0 and gl != gr:
            return r if gr > gl else l
    if (rules & 8):
        if (l, r) in [('[',']'), (']','['), ('{','}'), ('}','{'), ('(',')'), (')','(')]:
            return '|'
    if (rules & 16):
        if l == '/' and r == '\\': return '|'
        if l == '\\' and r == '/': return 'Y'
        if l == '>' and r == '<': return 'X'
    if (rules & 32) and l == hardblank and r == hardblank:
        return hardblank
    return None


def overlay(lines, glyph, overlap, rules, hardblank, universal=False):
    out=[]
    h=len(lines)
    for i in range(h):
        left = lines[i]
        right = glyph[i]
        if overlap <= 0:
            out.append(left + right)
            continue
        # pad left if overlap reaches before beginning
        if overlap > len(left):
            left = ' ' * (overlap - len(left)) + left
        prefix = left[:-overlap] if overlap else left
        mid=[]
        for k in range(overlap):
            lc = left[len(left)-overlap+k] if len(left)-overlap+k >= 0 else ' '
            rc = right[k] if k < len(right) else ' '
            sc = smush_pair(lc, rc, rules, hardblank, universal)
            if sc is None:
                sc = rc if rc != ' ' else lc
            mid.append(sc)
        suffix = right[overlap:] if overlap < len(right) else ''
        out.append(prefix + ''.join(mid) + suffix)
    return out


def valid_overlap(lines, glyph, overlap, mode, rules, hardblank, universal=False):
    if overlap < 0: return False
    if overlap == 0: return True
    for i in range(len(lines)):
        left=lines[i]; right=glyph[i]
        if overlap > len(left) + len(right):
            return False
        for k in range(overlap):
            li = len(left)-overlap+k
            lc = left[li] if 0 <= li < len(left) else ' '
            rc = right[k] if k < len(right) else ' '
            if lc != ' ' and rc != ' ':
                if mode == 'kern':
                    return False
                if smush_pair(lc, rc, rules, hardblank, universal) is None:
                    return False
    return True


def choose_overlap(lines, glyph, mode, rules, hardblank):
    if not lines or mode == 'full':
        return 0, False
    if all(len(x)==0 for x in lines):
        return 0, False
    max_possible = max([len(x) for x in lines] + [0]) + max([len(x) for x in glyph] + [0])
    if mode == 'overlap':
        # First kern as much as possible, then overlap one extra column if useful.
        kbest = 0
        for o in range(1, max_possible+1):
            if valid_overlap(lines, glyph, o, 'kern', rules, hardblank):
                kbest = o
            else:
                break
        if max(len(g) for g in glyph) > 1:
            return kbest + 1, True
        return kbest, True
    best = 0
    for o in range(1, max_possible+1):
        if valid_overlap(lines, glyph, o, mode, rules, hardblank, universal=False):
            best = o
        else:
            break
    return best, False


def font_default_mode(font):
    fl = font.fulllayout
    if fl is not None:
        if fl & 128:
            return 'smush', fl & 63
        if fl & 64:
            return 'kern', fl & 63
        return 'full', fl & 63
    old = font.oldlayout
    if old < 0: return 'full', 0
    if old == 0: return 'kern', 0
    return 'smush', old & 63


def render_chars(chars, font, layout_mode, rules, direction=0):
    if not chars:
        return ['' for _ in range(font.height)]
    seq = list(chars)
    if direction == 1:
        seq = list(reversed(seq))
    lines = ['' for _ in range(font.height)]
    for ch in seq:
        cp = ord(ch)
        if ch == '\t': cp = 32
        if cp < 32 and ch != '\t':
            continue
        glyph = font.glyphs.get(cp)
        if glyph is None:
            # Missing FIGcharacters are silently skipped.
            continue
        # Ensure height and copy strings.
        g = [(glyph[i] if i < len(glyph) else '') for i in range(font.height)]
        if all(len(x)==0 for x in lines):
            lines = g[:]
        else:
            o, uni = choose_overlap(lines, g, layout_mode, rules, font.hardblank)
            lines = overlay(lines, g, o, rules, font.hardblank, universal=uni)
    return lines


def visible_lines(lines, hardblank):
    return [l.replace(hardblank, ' ') for l in lines]


def max_line_len(lines):
    return max((len(x) for x in lines), default=0)


def justify(lines, width, just):
    if just == 'left':
        return lines
    maxw = max(1, width - 1)
    out=[]
    for l in lines:
        if just == 'right':
            pad = max(0, maxw - len(l))
        else:
            pad = max(0, (maxw - len(l)) // 2)
        out.append(' ' * pad + l)
    return out


def render_stream_text(text, font, layout_mode, rules, width, just, direction=0, paragraph=False):
    # Convert paragraph-mode newlines per the manual.
    if paragraph:
        res=[]
        n=len(text)
        for i,ch in enumerate(text):
            if ch == '\n':
                prev = text[i-1] if i>0 else '\n'
                nxt = text[i+1] if i+1<n else ''
                if prev != '\n' and nxt != '' and nxt not in ' \t\n\r\v\f':
                    res.append(' ')
                else:
                    res.append('\n')
            else:
                res.append(ch)
        text=''.join(res)
    output=[]
    current=[]
    maxw = max(1, width - 1)
    def flush(chars):
        lines = visible_lines(render_chars(chars, font, layout_mode, rules, direction), font.hardblank)
        output.extend(justify(lines, width, just))
    for ch in text:
        if ch == '\r':
            continue
        if ch == '\n':
            flush(current)
            current=[]
            continue
        if ch == '\t': ch = ' '
        if ord(ch) < 32:
            continue
        trial = current + [ch]
        lines = visible_lines(render_chars(trial, font, layout_mode, rules, direction), font.hardblank)
        if current and max_line_len(lines) > maxw:
            if ch != ' ' and ' ' in current:
                pos = len(current) - 1 - current[::-1].index(' ')
                before = current[:pos]
                after = current[pos+1:]
                flush(before)
                current = after
                # discard the breaking space; otherwise add current ch below
                trial = current + [ch]
                lines = visible_lines(render_chars(trial, font, layout_mode, rules, direction), font.hardblank)
                if current and max_line_len(lines) > maxw:
                    flush(current); current=[]
            else:
                flush(current)
                current=[]
        if ch == ' ' and not current:
            # FIGlet does not start wrapped lines with the word-separating blank.
            continue
        current.append(ch)
    if current:
        flush(current)
    return output


def parse_escaped_token(tok):
    if tok.startswith('\\0x') or tok.startswith('\\0X'):
        try: return chr(int(tok[1:], 16))
        except Exception: return ''
    if tok.startswith('0x') or tok.startswith('0X'):
        try: return chr(int(tok, 16))
        except Exception: return ''
    if tok.startswith('\\-'):
        try: return chr(int(tok[2:]))
        except Exception: return ''
    if tok.startswith('\\') and len(tok) > 1:
        escapes={'n':'\n','t':'\t','r':'\r','b':'\b','f':'\f'}
        return escapes.get(tok[1], tok[1])
    return tok[0] if tok else ''


def load_control(path):
    maps={}
    utf8=False
    data=open(path,'rb').read()
    text=data.decode('utf-8','replace')
    lines=text.splitlines()
    # Unicode mapping table format: 0xXX 0xYYYY ...
    for line in lines:
        s=line.strip()
        if not s or s.startswith('#'):
            continue
        if s == 'u':
            utf8=True; continue
        if s.startswith('&') or s.startswith('flc2'):
            continue
        parts=s.split()
        if not parts: continue
        if parts[0] == 't' and len(parts) >= 3:
            src=parse_escaped_token(parts[1]); dst=parse_escaped_token(parts[2])
            if src and dst: maps[src]=dst
            continue
        if len(parts) >= 2 and parts[0].lower().startswith('0x') and parts[1].lower().startswith('0x'):
            try:
                src=chr(int(parts[0],16)); dst=chr(int(parts[1],16)); maps[src]=dst
            except Exception:
                pass
    return maps, utf8


def apply_controls(text, controls, german=False):
    maps=[]
    if german:
        maps.append({'@':'§','[':'Ä','\\':'Ö',']':'Ü','{':'ä','|':'ö','}':'ü','~':'ß'})
    maps.extend(controls)
    if not maps:
        return text
    out=[]
    for ch in text:
        c=ch
        for m in maps:
            c=m.get(c,c)
        out.append(c)
    return ''.join(out)


def build_message(args):
    if not args:
        return None
    out=[]
    prev_nonempty=False
    for a in args:
        if a == '':
            if prev_nonempty:
                out.append(' ')
            out.append('\n')
            prev_nonempty=False
        else:
            if prev_nonempty:
                out.append(' ')
            out.append(a)
            prev_nonempty=True
    return ''.join(out)

class Opts:
    def __init__(self):
        self.fontdir=DEFAULT_FONTDIR
        self.font=DEFAULT_FONT
        self.width=80
        self.just='auto'
        self.direction='font'
        self.paragraph=False
        self.layout_request=None  # None, full,kern,smush,force_smush,overlap, explicit
        self.explicit_rules=None
        self.info=-1
        self.operands=[]
        self.german=False
        self.controls=[]
        self.control_files=[]


def usage(prog):
    return USAGE_TPL.format(prog=prog)


def parse_args(argv):
    opts=Opts()
    prog_path=argv[0] if argv else 'executable'
    prog=os.path.basename(prog_path)
    req=set('dfmwCI')
    simple=set('cklnoprstvxDELNRSWX')
    i=1
    endopts=False
    while i < len(argv):
        arg=argv[i]
        if endopts or arg == '-' or not (arg.startswith('-') and len(arg)>1):
            opts.operands.append(arg); i+=1; continue
        if arg == '--':
            opts.operands.extend(argv[i+1:]); break
        j=1
        while j < len(arg):
            ch=arg[j]
            if ch in req:
                if j+1 < len(arg):
                    val=arg[j+1:]; j=len(arg)
                else:
                    if i+1 >= len(argv):
                        sys.stderr.write(f"{prog_path}: option requires an argument -- '{ch}'\n")
                        sys.stderr.write(usage(prog)); return None, 1
                    i+=1; val=argv[i]; j=len(arg)
                if ch == 'd': opts.fontdir=val
                elif ch == 'f': opts.font=val
                elif ch == 'w':
                    try: opts.width=int(val)
                    except Exception: pass
                    if opts.width < 1: opts.width=80
                elif ch == 'm':
                    try: mv=int(val)
                    except Exception: mv=0
                    if mv == 0: opts.layout_request='kern'
                    elif mv == -1: opts.layout_request='full'
                    elif mv == -2: opts.layout_request='smush'
                    elif 1 <= mv <= 63:
                        opts.layout_request='explicit'; opts.explicit_rules=mv
                elif ch == 'C':
                    opts.control_files.append(val)
                elif ch == 'I':
                    try: opts.info=int(val)
                    except Exception: opts.info=0
                break
            elif ch in simple:
                if ch == 'c': opts.just='center'
                elif ch == 'l': opts.just='left'
                elif ch == 'r': opts.just='right'
                elif ch == 'x': opts.just='auto'
                elif ch == 'p': opts.paragraph=True
                elif ch == 'n': opts.paragraph=False
                elif ch == 'D': opts.german=True
                elif ch == 'E': opts.german=False
                elif ch == 'N': opts.control_files=[]; opts.controls=[]
                elif ch == 'L': opts.direction='ltr'
                elif ch == 'R': opts.direction='rtl'
                elif ch == 'X': opts.direction='font'
                elif ch == 'v': opts.info=0
                elif ch == 't':
                    try:
                        sz=shutil.get_terminal_size(fallback=(opts.width, 24))
                        if sz.columns > 0 and sys.stdout.isatty(): opts.width=sz.columns
                    except Exception: pass
                elif ch == 's': opts.layout_request='smush'
                elif ch == 'S': opts.layout_request='force_smush'
                elif ch == 'k': opts.layout_request='kern'
                elif ch == 'W': opts.layout_request='full'
                elif ch == 'o': opts.layout_request='overlap'
                # deprecated/no-op: none
                j+=1
            else:
                sys.stderr.write(f"{prog_path}: invalid option -- '{ch}'\n")
                sys.stderr.write(usage(prog)); return None, 1
        i+=1
    return opts, 0


def print_version(prog):
    sys.stdout.write(VERSION_TEXT)
    sys.stdout.write(usage(prog))


def main(argv):
    prog=os.path.basename(argv[0] if argv else 'executable')
    opts, err = parse_args(argv)
    if err:
        return err
    # Load control files during normal rendering; info modes should not fail on them in classic FIGlet?
    if opts.info >= 0:
        if opts.info == 0:
            print_version(prog)
        elif opts.info == 1:
            sys.stdout.write('20205\n')
        elif opts.info == 2:
            sys.stdout.write(opts.fontdir + '\n')
        elif opts.info == 3:
            sys.stdout.write(strip_suffix_font_name(opts.font) + '\n')
        elif opts.info == 4:
            sys.stdout.write(str(opts.width) + '\n')
        elif opts.info == 5:
            sys.stdout.write('flf2 tlf2\n')
        return 0
    control_maps=[]
    for cf in opts.control_files:
        p=find_control(opts.fontdir, cf)
        if not p:
            sys.stderr.write(f"{prog}: {cf}: Unable to open control file\n")
            return 1
        m, u = load_control(p)
        control_maps.append(m)
    path=find_font(opts.fontdir, opts.font)
    if not path:
        sys.stderr.write(f"{prog}: {opts.font}: Unable to open font file\n")
        return 1
    try:
        font=load_font(path)
    except Exception:
        sys.stderr.write(f"{prog}: {opts.font}: Unable to open font file\n")
        return 1
    mode, rules = font_default_mode(font)
    if opts.layout_request == 'full': mode='full'; rules=0
    elif opts.layout_request == 'kern': mode='kern'; rules=0
    elif opts.layout_request == 'overlap': mode='overlap'; rules=0
    elif opts.layout_request == 'explicit': mode='smush'; rules=opts.explicit_rules or 0
    elif opts.layout_request == 'force_smush':
        mode='smush'; rules = (font.fulllayout & 63) if font.fulllayout is not None else (font.oldlayout & 63 if font.oldlayout>0 else 0)
        if rules == 0: mode='overlap'
    elif opts.layout_request == 'smush':
        # Respect fonts whose declared default is fitting or full width.
        dm, dr = font_default_mode(font)
        if dm == 'smush': mode='smush'; rules=dr
        else: mode=dm; rules=dr
    direction = font.printdir
    if opts.direction == 'ltr': direction=0
    elif opts.direction == 'rtl': direction=1
    just=opts.just
    if just == 'auto':
        just = 'right' if direction == 1 else 'left'
    msg=build_message(opts.operands)
